INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('faq', 'AI口コミ返信ジェネレーターとは何ですか？', 'Google マップ・食べログ・じゃらんなど8つのプラットフォームの口コミに対し、あなたのお店らしいAI返信を数秒で自動生成するツールです。プロファイル設定（温かみ・ユーモア・丁寧さなど5軸）で個性を学習させることで、テンプレート感のない返信ができます。', ARRAY['口コミ','返信','AI','ジェネレーター'], 'review-reply-ai'),
('faq', 'どのプラットフォームの口コミに対応していますか？', 'Google マップ、食べログ、じゃらん、楽天トラベル、Hotpepper Beauty、ホットペッパーグルメ、Amazon、その他（8種類）に対応しています。口コミ文をコピーして貼り付けるだけで使えます。', ARRAY['プラットフォーム','対応','Google','食べログ'], 'review-reply-ai'),
('pricing', '料金はいくらですか？（review-reply-ai）', 'Free プランは登録後5回/日まで無料で使えます。Pro プランは月390円（1日13円）で無制限利用・返信プロファイル5名分・90日間の履歴保存・多言語対応が使えます。いつでも解約可能です。', ARRAY['料金','価格','無料','Pro','プラン'], 'review-reply-ai'),
('faq', 'どの業種に対応していますか？', '飲食店、美容院・ネイルサロン、クリニック・歯科、ホテル・旅館、小売店・雑貨店、整体・マッサージ、不動産、その他の8業種に対応しています。業種ごとに適切な表現（患者様・お客様・ご宿泊など）を自動調整します。', ARRAY['業種','業界','対応','飲食','美容','クリニック'], 'review-reply-ai'),
('faq', 'ネガティブな口コミ（低評価）にも対応できますか？', 'はい、むしろネガティブ口コミ対応が最も価値を発揮します。感情的にならずに「謝罪→改善の姿勢→再来店促進」の流れで返信を生成します。プロファイル設定でお店のキャラクターを保ったまま対応できます。', ARRAY['ネガティブ','低評価','クレーム','苦情'], 'review-reply-ai'),
('faq', '外国語の口コミにも対応していますか？', 'Pro プランでは日本語・英語・中国語・韓国語の口コミに対応し、返信も各言語で生成できます。訪日外国人が増えている地域のお店に特に喜ばれています。', ARRAY['多言語','外国語','英語','中国語','韓国語'], 'review-reply-ai'),
('feature', '返信プロファイルとは何ですか？', '温かみ・ユーモア・具体性・丁寧さ・共感力の5軸で、あなたやスタッフの返信スタイルをAIに学習させる機能です。Pro では5名分登録でき、スタッフごとにキャラクターを使い分けた返信が可能です。6種のペルソナテンプレート（おもてなし店長・人情派オーナーなど）から始めることもできます。', ARRAY['プロファイル','カスタマイズ','個性','ペルソナ'], 'review-reply-ai'),
('faq', 'セキュリティは大丈夫ですか？（review-reply-ai）', 'Supabase（Row Level Security）で自分のデータのみアクセス可能です。貼り付けた口コミテキストはAI生成後は保持しません（履歴機能はProのみ90日保存）。決済はStripeを使用しておりカード情報は当サービスに渡りません。', ARRAY['セキュリティ','安全','データ','個人情報'], 'review-reply-ai')
INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('competitor', 'ChatGPT/Claudeと比べてどう違いますか？（review-reply-ai）', 'プロファイル5軸でお店ごとの個性を保ったまま返信。業種別最適化（医療広告ガイドライン対応など）。口コミを貼るだけで2パターン＋客層分析が同時に出る。月390円で無制限。ChatGPTで返信を作る人が最終チェックに使うツールです。', ARRAY['競合','ChatGPT','Claude','比較','メリット'], 'review-reply-ai'),
('competitor', 'ホットペッパーや食べログの返信機能と何が違いますか？', '複数プラットフォームを1つのツールで統一対応。プロファイル学習でお店らしさを保持。ネガティブ口コミ対応特化機能。客層分析でマーケ施策につなげられます。Googleマップ・食べログ・じゃらんなど複数サイトを横断して統一返信スタイルを維持したい店舗向けです。', ARRAY['競合','ホットペッパー','食べログ','比較'], 'review-reply-ai')
INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('objection', '自分で返信を書いた方が早いのでは？', '1件あたり平均5-10分かかる口コミ返信が、数秒で2パターン生成されます。1日5件の口コミに返信する場合、月10時間以上の削減になります。さらにプロファイル設定でお店の個性を維持できるため、品質も安定します。', ARRAY['時間','効率','手動','自分で'], 'review-reply-ai'),
('objection', 'AIの返信は不自然にならない？', 'プロファイル5軸（温かみ・ユーモア・具体性・丁寧さ・共感力）でお店独自のキャラクターを学習させるため、テンプレート感のない返信が可能です。6種のペルソナテンプレートから始めて微調整することもできます。', ARRAY['不自然','テンプレ','品質','AI'], 'review-reply-ai'),
('objection', '月390円の価値はありますか？', '1日13円で無制限の口コミ返信が可能です。返信1件にかかる時間コスト（5-10分×時給換算）と比較すると、月数件の返信だけで元が取れます。さらに多言語対応・履歴保存・5名分のプロファイルが含まれます。', ARRAY['価値','コスト','料金','元が取れる'], 'review-reply-ai')
INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('faq', 'MsgScoreは何ができますか？', 'メール・LINE配信文をAIがスコアリングし、開封率・CTR・CV数を予測するツールです。送る前に文章の改善点がわかり、より効果的な配信文を作れます。', ARRAY['機能','スコア','予測','分析'], 'msgscore'),
('pricing', '料金はいくらですか？（MsgScore）', 'Free プランは1日5回まで無料で使えます。Pro プランは月980円（税込）で1日50回まで利用でき、詳細なスコア分析や改善提案も表示されます。', ARRAY['料金','価格','無料','Pro','プラン'], 'msgscore'),
('faq', 'どんなチャネルに対応していますか？', 'メール件名・メール本文・LINEメッセージの3チャネルに対応しています。チャネルごとに最適なスコアリング基準を適用します。', ARRAY['チャネル','対応','メール','LINE'], 'msgscore'),
('faq', 'AIの予測精度はどのくらいですか？', '業界ベンチマークと機械学習モデルをベースに、開封率・CTR・CVRを予測しています。実際の配信結果と比較した内部テストでは、相関係数0.7以上を確認しています。', ARRAY['精度','予測','スコア','信頼性'], 'msgscore'),
('faq', '登録は必要ですか？', 'Free プランは登録なしでもお試しいただけます。利用履歴の保存やPro機能には無料アカウント登録（メールアドレスのみ）が必要です。', ARRAY['登録','アカウント','ログイン'], 'msgscore'),
('faq', 'セキュリティは大丈夫ですか？（MsgScore）', '入力した文章はスコアリング処理のみに使用し、外部に共有・販売することはありません。通信はすべてSSL暗号化されています。', ARRAY['セキュリティ','安全','データ','個人情報'], 'msgscore'),
('faq', 'チーム・複数人で使えますか？', 'Pro プランのチーム機能で複数メンバーの招待・権限管理が可能です。チーム全体でスコア履歴を共有できます（近日公開予定）。', ARRAY['チーム','複数人','共有','メンバー'], 'msgscore'),
('faq', '解約はできますか？', 'いつでもマイページから即座に解約できます。解約後は月末まで Pro 機能が使え、翌月以降は Free プランに自動移行します。', ARRAY['解約','キャンセル','退会'], 'msgscore')
INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('competitor', '海外の配信ツール（Mailchimp等）と何が違いますか？', '日本語に特化したスコアリング。日本のメール慣習・敬語・開封率ベンチマークを学習しています。海外ツールは英語基準のため、日本語文章の評価精度が低いです。MsgScoreは「配信する前の文章チェック・改善」に特化したツールで、既存の配信ツールと併用できます。', ARRAY['競合','Mailchimp','海外','比較'], 'msgscore'),
('competitor', '国内配信ツール（配配メール等）と何が違いますか？', 'スコアリング・予測に特化。配信ツールとは競合せず、むしろ組み合わせて使うことでより効果的です。配配メールで配信し、MsgScoreで文章を事前チェックするワークフローが最適です。価格も月980円と大幅に安いです。', ARRAY['競合','配配メール','国内','比較'], 'msgscore'),
('competitor', 'ChatGPT/Claudeと比べてどう違いますか？（MsgScore）', 'MsgScoreは日本のメール配信特化の評価基準（開封率・CTR・CV）でスコア化し、数値として見える化します。汎用AIへのプロンプト設計不要で、すぐに使えます。ChatGPTで文章を作り、MsgScoreでスコアチェックする使い方が多いです。', ARRAY['競合','ChatGPT','Claude','比較','メリット'], 'msgscore')
INSERT INTO sales_knowledge (category, question, answer, keywords, product) VALUES
('objection', 'スコアが低いメールでも実際は効果があるのでは？', 'もちろんスコアは1つの指標です。ただし、内部テストでスコアと実績の相関係数0.7以上を確認しています。スコアが低い文章の具体的な改善ポイントを確認して、より高い確率で成果を出せるようにするのがMsgScoreの価値です。', ARRAY['スコア','精度','効果','信頼性'], 'msgscore'),
('objection', '月980円の価値はありますか？（MsgScore）', '1通のメール配信で数千人にリーチするなら、開封率が1%改善するだけで数十人の追加閲覧が見込めます。月980円で毎日50回までスコアチェックでき、配信前の品質管理として非常にコスパの良い投資です。', ARRAY['価値','コスト','料金','元が取れる'], 'msgscore')
